}

pair F, P, Q;

F = (0,1/4);
P = (0.8,func(0.8));
Q = (0.8,-1/4);

draw(graph(func,-1,1));
draw((-1,-1/4)--(1,-1/4),dashed);
draw(F--P--Q);

label("$y = -1$", (1,-1/4), E);
label("$y + 1$", (P + Q)/2, E);

dot("$F = (0,1)$", F, NW);
